\label{thm:main}
   Let $C$ be a geometrically irreducible smooth projective curve over a field $k$ of genus $g\geq 2$ and $C$ admits a $k$-rational point. Let $L$ be line bundle on $C$ and $n\geq 1$. Then 
    the moduli stack $Sympl_{2n, L}$ of rank $2n$ symplectic vector bundles  on $C$ is $\#A^1$-connected.

\label{intro-thm:quasi-parabolic-sympl}
        Let $C$ be a geometrically irreducible smooth projective curve of genus $g\geq 2$ over a field $k$ and a finite subset $D \subset C$ of distinct $k$-rational points. Fix a quasi-parabolic data $(e, \_m)$ on $C$ of rank $2n$ along $D$ in the sense of~\Cref{def:quasi-para-data}. 

    Then $qPSympl^{e, \_m}_{2n, L}$ is $\#A^1$-connected.

\label{def:naive-chain-A1}
    Let $\@X$ be a simplicial presheaf on ${\rm Sm}/k$. Define $\@S(\@X)$, \emph{the sheaf of naive $\#A^1$-chain connected components of $\@X$}, as the Nisnevich sheafification of the presheaf  on ${\rm Sm}/k$ assigning $$U\mapsto {\@X(U)_0}/\sim$$ for each $U$ in ${\rm Sm}/k$ where $\sim$ is the equivalence relation generated by naive $\#A^1$-homotopies. 

    We say $\@X$ is naively $\#A^1$-chain connected if for each finitely generated field extension $K$ of $k$, $\@S(\@X)(K)=*$.

(\cite[Section 2,
Corollary 3.22]{MV99} with~\cite[Lemma 6.1.3.]{Mor05})\label{lem:a1-chain-a1-conn}
    Let $\@X$ be a simplicial presheaf on ${\rm Sm}/k.$ If $\@X$ is naively $\#A^1$-chain connected {\it i.e.\/},\  $\@S(\@X)(K)=*$ for each finitely generated field extension $K$ of $k$, then $\@X$ is $\#A^1$-connected.

\label{lem:modify-1-family} 

Let $\@E$ be a vector bundle on $C\times \#A^1_K$  such that $i_0^*\@E$ is semistable on $C$ via  $i_0: C=C\times \{0\}\to C\times \#A^1_K$. Let $U\subset \#A^1_K$ be the maximal semistable locus of $\@E$ in $C$. Assume that $1\notin U$. Then there exists a vector bundle $\~{\@E}$ on  $C\times \#A^1_K$  such that 
\begin{enumerate}
\item $\~{\@E}$ is semistable on  $C\times (\#A^1_K-\{1\})$ 
\item $\~{\@E}|_{C\times \{1\}}= \@E|_{C\times \{1\}}$ and
    \item $\~{\@E}|_{C\times U}= \@E|_{C\times U}.$    
\end{enumerate}

\label{prop:ext}
Let $C$ be a geometrically irreducible smooth projective curve over a field $k$ of genus $g\geq 2$ and let $K$ be a finitely generated field extension of $k$. Let $\@Q, \@K, \~{\@K}$ be vector bundles on $C\times_k \#A^1_K$. Let $f: \~{\@K}\to \@K$ be a surjective morphism of vector bundles. Assume the diagram  $$\xymatrix{
   \@M \ar[r]^-{\phi} \ar[d]^{\gamma} & \@Ext(\@Q, \~{\@K})  \ar[d]^{f_*} \\ 
   \#A^1_K\ar[r] &  \@Ext(\@Q, \@K) 
   }$$  is a cartesian diagram of stacks over the field $k$. Then the following holds:
   \noindent\begin{enumerate}
       \item $\@Ext(\@Q, \~{\@K})$ and $\@Ext(\@Q, \@K)$ are representable by vector bundles over $\#A^1_K.$ 
       \item The morphism $f_*$ is representable by surjective morphism of vector bundles over $\#A^1_K.$
   \item   Any two $K$-points of $\@M$ are naively $\#A^1$-chain connected. 
   \end{enumerate}

\noindent\begin{enumerate}
        \item $\@Ext(\@Q, \~{\@K})$ is given by groupoid for each $\#A^1_K$-scheme $S$,  
        \begin{itemize}
            \item the objects are exact sequences $0\to q_S^*(\~{\@K}) \to \~{\@E}\to q_S^*(\@Q) \to 0$ of vector bundles on $C\times_k S$ where $q_S: C\times_k S\to C\times \#A^1_K.$ 
            \item the morphisms are morphisms of exact sequences. 
        \end{itemize}
       Let $p: C\times \#A^1_K\to \#A^1_K$ be the projection morphism and $p_S: C\times_k S\to C$ the base change and $q_S: C\times S\to C\times\#A^1_K$ induced morphism. The moduli stack $\@Ext(\@Q, \~{\@K})$ is given by $$S\mapsto  H^0(S, {\bf Ext^1}_{p_S}(q_S^*\@Q,q_S^*\~{\@K}))$$  By \cite[Proposition 3.1]{Lan83}, this functor is representable by a vector bundle over $\#A^1_K.$ This vector bundle is trivial by Quillen-Suslin theorem (\cite{Qui76}, \cite{Sus76}), hence represented by an affine space. 

       Similarly, the moduli stack $\@Ext(\@Q, \@K)$ is representable by a vector bundle over $\#A^1_K.$

  \item By Yoneda's lemma, the morphism $f_*: \@Ext(\@Q, \~{\@K})\to \@Ext(\@Q, \@K)$ is induced by a morphism of vector bundles over $\#A^1_K.$ Since the morphism of stacks is surjective by~\cite[Proof of Lemma 3.8]{BH08}, the map of vector bundles is surjective. 

  \item By (2), since the diagram is cartesian commutative, the morphism $\gamma$ is representable by the structure morphism of a vector bundle over  $\#A^1_K$, which is trivial hence isomorphic to an affine space. Let $e_1, e_2$ be two $K$-points of $\@M$. The points correspond to $K$-points of an affine space over $K,$ hence there is a naive $\#A^1$-homotopy from   $e_1$ to $ e_2$. 
  \end{enumerate}

\label{thm:main-text}
   Let $C$ be a geometrically irreducible smooth projective curve over a field $k$ of genus $g\geq 2$ and $C(k)\neq \emptyset$. Let $L$ and $I$ be line bundles on $C$ and $n\geq 1$. Then 
   \begin{enumerate}
       \item The moduli stack $\@Ext(\@F^{univ}, I, 2n-2)$ is naively $\#A^1$-chain connected, hence $\#A^1$-connected. 
       \item The stack $\@Sub_{1, I, 2n}(\@E^{univ})$ is naively $\#A^1$-chain connected, hence $\#A^1$-connected. 
       \item The moduli stack $Sympl_{2n, L}$ of rank $2n$ symplectic vector bundles  on $C$ is naively $\#A^1$-chain connected for each $n\geq 1$, hence $\#A^1$-connected. 


   \end{enumerate}

\label{def:quasi-para-data} 
    A quasi-parabolic data $(e, \_m)$ on $C$ of rank $2n$ along $D$ is defined as follows: 
\begin{itemize}
    \item For each point $p\in D$, $e(p)\in \#N$ and a tuple of postive integers $\_m(p)=(m_{p, 1}, \dots, m_{p, e(p)})$ such that $m_{p, 1}+ \dots+ m_{p, e(p)}=2n.$
\item The set $e=\{e(p) : p\in D\}$ is the system of lengths. 
\item The set $\_m=\{\_m(p) : p\in D\}$ is the system of multiplicities.
\end{itemize}

\label{def:q-parabolic}

Fix a line bundle $L$ on $C$ and a quasi-parabolic data $(e, \_m)$ on $C$ of rank $2n$ along $D$. 

For any $k$-scheme $S$ and the projection $\pi: C\times_k S\to C$, a quasi-parabolic bundle of rank $2n$ parametrized by $S$ of quasi-parabolic data $(e, \_m)$ denoted by $\@E_*$  given by
\begin{itemize}
    \item a vector bundle $\@E$ on $C\times S$
   \item for each $p\in D$, there is a flag of vector bundles of the pull back vector bundle $\@E_p=\@E|_{\{p\}\times S}$ on $\{p\}\times S$ 
$$\@E_p= \@E_{p, 1}\supsetneq \cdots \supsetneq \@E_{p, e(p)}\supsetneq  \@E_{p, e(p)+1}=\{0\}$$
such that 
\begin{itemize}

 \item $e(p)$ is the length of the flag and 
    \item  $m_{p,i}={\rm rank}~\@E_{p,i}-{\rm rank}~\@E_{p,i+1}$ are called multiplicities at p.
\end{itemize}
\end{itemize}

     We recall the following definition. We note that usually the following definition is considered when the base field is complex numbers.

\label{def:moduli-q-para-sympl}
    Fix a line bundle $L$ on $C$ and a quasi-parabolic data $(e, \_m)$ on $C$ of rank $2n$ along $D$. One endows $L(D)$ with a parabolic bundle structure where for each point $p\in D,$ with a filtration $\@L_p\supset 0$ as in \cite[Remark 2.2]{BCD26}. 

One defines the Moduli stack $qPSympl^{e, \_m}_{2n, L(D)}$ of quasi-Parabolic symplectic bundles of rank $2n$ on $C$ as follows. 
More precisely, on each $k$-scheme $S$, the groupoid is given by 
\begin{itemize}
    \item the objects are $(\@E_*, \phi_*, \@L(D))$ where $$\phi_*: \@E_*\otimes \@E_*\to \@L(D)$$ where $\@E_*$ is a symplectic quasi-parabolic bundle on $C\times_k S$ in the sense of \Cref{def:q-parabolic-sympl}, \cite[Definition 2.4]{BCD26} and $\@L$ a line bundle on $C\times_k S$, Zariski locally on $S$ isomorphic to $\pi^*L$ where $\pi:C\times_k S\to C$ is the projection. 
    \item the morphism  $(\@E_*, \phi_*, \@L(D))\to (\@E'_*, \phi'_*, \@L'(D))$ is an isomorphism of underlying parabolic bundles and isomorphism of parabolic line bundles $\@L(D) \to \@L'(D)$ compatible with the anti-symmetric bilinear forms $\phi, \phi'.$ 
\end{itemize}

\label{thm:quasi-parabolic-sympl}
        Let $C$ be a geometrically irreducible smooth projective curve of genus $g\geq 2$ over a field $k$ and a finite subset $D \subset C$ of distinct $k$-rational points. Fix a quasi-parabolic data $(e, \_m)$ on $C$ of rank $2n$ along $D$. 

    Then $qPSympl^{e, \_m}_{2n, L}$ is $\#A^1$-connected.
